<script lang="ts">
	import { onMount } from 'svelte';
	import LegalNetwork from '$lib/legal/LegalNetwork.svelte';
	import type { LegalCatalogue, LegalRecord } from '$lib/legal/types';
	let catalogue: LegalCatalogue | null = null, loadError = '', query = '', status = '', house = '', billType = '', category = '', ministry = '';
	let yearFrom = 1952, yearTo = new Date().getFullYear(), page = 1, selected: LegalRecord | null = null;
	let view: 'list' | 'network' = 'list';
	const pageSize = 40;
	onMount(async () => { try { const response = await fetch('/data/legal-explorer.json'); if (!response.ok) throw new Error(`Catalogue request failed (${response.status})`); catalogue = await response.json(); yearFrom = catalogue?.meta.dateMin ?? 1952; yearTo = catalogue?.meta.dateMax ?? new Date().getFullYear(); } catch (error) { loadError = error instanceof Error ? error.message : 'The catalogue could not be loaded.'; } });
	$: records = catalogue?.records ?? [];
	$: statuses = unique(records.map((r) => r.status)); $: houses = unique(records.map((r) => r.introducedInHouse)); $: billTypes = unique(records.map((r) => r.billType)); $: categories = unique(records.map((r) => r.category)); $: ministries = unique(records.map((r) => r.ministry));
	$: needle = query.trim().toLocaleLowerCase('en-IN');
	$: filtered = records.filter((r) => `${r.title} ${r.billNumber ?? ''} ${r.ministry ?? ''} ${r.introducedBy ?? ''} ${r.actNumber ?? ''}`.toLocaleLowerCase('en-IN').includes(needle) && (!status || r.status === status) && (!house || r.introducedInHouse === house) && (!billType || r.billType === billType) && (!category || r.category === category) && (!ministry || r.ministry === ministry) && (r.year === null || r.year >= yearFrom) && (r.year === null || r.year <= yearTo));
	$: totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
	$: {
		if (page > totalPages) page = totalPages;
	}
	$: visible = filtered.slice((page - 1) * pageSize, page * pageSize);
	function unique(values: Array<string | null>) { return [...new Set(values.filter((v): v is string => Boolean(v)))].sort((a,b) => a.localeCompare(b)); }
	function setFilter() { page = 1; selected = null; }
	function clearFilters() { query = status = house = billType = category = ministry = ''; yearFrom = catalogue?.meta.dateMin ?? 1952; yearTo = catalogue?.meta.dateMax ?? new Date().getFullYear(); setFilter(); }
	function displayDate(value: string | null) { if (!value) return 'Not recorded'; const date = new Date(`${value.slice(0,10)}T00:00:00`); return Number.isNaN(date.valueOf()) ? value : new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric'}).format(date); }
	function documentLinks(r: LegalRecord) { return [['As introduced',r.documents.introduced],['Passed by Lok Sabha',r.documents.passedLokSabha],['Passed by Rajya Sabha',r.documents.passedRajyaSabha],['Passed by both Houses',r.documents.passedBothHouses],['Committee report',r.documents.committeeReport],['Gazette',r.documents.gazette],['Synopsis',r.documents.synopsis],['Errata',r.documents.errata]].filter((e): e is [string,string] => Boolean(e[1])); }
</script>

<svelte:head><title>Legal Explorer — Anindya Singh</title><meta name="description" content="Search and trace Indian parliamentary bills from official Digital Sansad records." /></svelte:head>

<section class="legal-page">
	<header class="hero"><div><p class="eyebrow">Independent public research tool · beta</p><h1>Legal<br />Explorer</h1></div><div class="hero-copy"><p class="lede">Trace parliamentary bills through introduction, passage, assent, committees, Acts, and official documents.</p><p>This is a catalogue, not legal advice. Imported records reproduce official metadata but have not all been checked by a human. Gazette documents remain authoritative.</p></div></header>
	{#if loadError}<div class="notice"><strong>Catalogue unavailable.</strong><span>{loadError}</span></div>
	{:else if !catalogue}<div class="loading" aria-live="polite"><span></span>Loading the parliamentary record…</div>
	{:else}
		<section class="desk" aria-label="Legal catalogue">
			<div class="stats"><div><strong>{catalogue.meta.recordCount.toLocaleString('en-IN')}</strong><span>unique records</span></div><div><strong>{catalogue.meta.dateMin}–{catalogue.meta.dateMax}</strong><span>reported years</span></div><div><strong>{filtered.length.toLocaleString('en-IN')}</strong><span>current result</span></div><div><strong>Official import</strong><span>verification state</span></div></div>
			<form class="filters" onsubmit={(e)=>e.preventDefault()} onchange={setFilter}>
				<label class="search"><span>Search title, number, ministry, member, or Act</span><input type="search" bind:value={query} oninput={setFilter} placeholder="Try citizenship, labour, forests…" /></label>
				<label><span>Status</span><select bind:value={status}><option value="">All statuses</option>{#each statuses as item}<option value={item}>{item}</option>{/each}</select></label>
				<label><span>House</span><select bind:value={house}><option value="">Both Houses</option>{#each houses as item}<option value={item}>{item}</option>{/each}</select></label>
				<label><span>Bill type</span><select bind:value={billType}><option value="">All types</option>{#each billTypes as item}<option value={item}>{item}</option>{/each}</select></label>
				<label><span>Category</span><select bind:value={category}><option value="">All categories</option>{#each categories as item}<option value={item}>{item}</option>{/each}</select></label>
				<label class="wide"><span>Ministry</span><select bind:value={ministry}><option value="">All ministries</option>{#each ministries as item}<option value={item}>{item}</option>{/each}</select></label>
				<label><span>From year</span><input type="number" min={catalogue.meta.dateMin ?? 1952} max={yearTo} bind:value={yearFrom} /></label><label><span>To year</span><input type="number" min={yearFrom} max={catalogue.meta.dateMax ?? 2026} bind:value={yearTo} /></label><button type="button" class="clear" onclick={clearFilters}>Clear filters</button>
			</form>
			<div class="view-switch" aria-label="Explorer view"><button type="button" class:active={view==='list'} onclick={()=>view='list'}>List</button><button type="button" class:active={view==='network'} onclick={()=>view='network'}>Connections</button></div>
			{#if view === 'network'}<LegalNetwork records={filtered} focus={selected} onselect={(record)=>selected=record} />{/if}
			<div class="workspace" class:has-selection={selected} class:network-detail={view==='network'}>
				<div class="results"><div class="result-head"><p>Showing {visible.length ? (page-1)*pageSize+1 : 0}–{Math.min(page*pageSize,filtered.length)} of {filtered.length.toLocaleString('en-IN')}</p><p>Newest first</p></div>
					{#if visible.length===0}<p class="empty">No records match this combination. Missing records can also reflect gaps in the source catalogue.</p>{:else}{#each visible as record (record.id)}<button class="record" class:selected={selected?.id===record.id} type="button" onclick={()=>selected=record}><span class="record-year">{record.year ?? 'Year n/a'}</span><span class="record-main"><strong>{record.title}</strong><small>{record.ministry ?? 'Ministry not recorded'}</small></span><span class="record-status">{record.status ?? 'Unlabelled'}</span></button>{/each}{/if}
					<nav class="pagination" aria-label="Result pages"><button type="button" disabled={page===1} onclick={()=>{page-=1;selected=null}}>← Previous</button><span>Page {page.toLocaleString('en-IN')} of {totalPages.toLocaleString('en-IN')}</span><button type="button" disabled={page===totalPages} onclick={()=>{page+=1;selected=null}}>Next →</button></nav>
				</div>
				{#if selected}<aside class="detail" aria-live="polite"><button class="close" type="button" aria-label="Close record" onclick={()=>selected=null}>×</button><p class="detail-kicker">{selected.billType ?? 'Bill'} · {selected.category ?? 'Uncategorised'}</p><h2>{selected.title}</h2><div class="verification"><span></span>Official metadata · not yet human-checked</div><dl><div><dt>Bill number</dt><dd>{selected.billNumber ?? 'Not recorded'}</dd></div><div><dt>Introduced</dt><dd>{displayDate(selected.introducedDate)} · {selected.introducedInHouse ?? 'House not recorded'}</dd></div><div><dt>Introduced by</dt><dd>{selected.introducedBy ?? 'Not recorded'}</dd></div><div><dt>Ministry</dt><dd>{selected.ministry ?? 'Not recorded'}</dd></div><div><dt>Lok Sabha passage</dt><dd>{displayDate(selected.passedLokSabhaDate)}</dd></div><div><dt>Rajya Sabha passage</dt><dd>{displayDate(selected.passedRajyaSabhaDate)}</dd></div><div><dt>Committee referral</dt><dd>{displayDate(selected.committeeReferralDate)}</dd></div><div><dt>Assent</dt><dd>{displayDate(selected.assentDate)}</dd></div><div><dt>Resulting Act</dt><dd>{selected.actNumber ? `${selected.actNumber} of ${selected.actYear ?? 'year not recorded'}` : 'Not recorded'}</dd></div><div><dt>Status</dt><dd>{selected.status ?? 'Not recorded'}</dd></div></dl><div class="documents"><h3>Official documents</h3>{#if documentLinks(selected).length}{#each documentLinks(selected) as [label,url]}<a href={url} target="_blank" rel="noopener">{label} ↗</a>{/each}{:else}<p>No document link accompanied this source record.</p>{/if}</div></aside>{/if}
			</div>
		</section>
		<section class="method"><div><p class="eyebrow">Source & limits</p><h2>Know what the catalogue cannot prove</h2></div><div><p>Generated {new Date(catalogue.meta.generatedAt).toLocaleString('en-IN')} from <a href={catalogue.meta.sourceUrl} target="_blank" rel="noopener">{catalogue.meta.sourceName} ↗</a>. The source reported {catalogue.meta.sourceReportedTotal.toLocaleString('en-IN')} rows; exact identity duplicates are consolidated here.</p><ul>{#each catalogue.meta.limitations as limitation}<li>{limitation}</li>{/each}</ul><a href="https://www.indiacode.nic.in/" target="_blank" rel="noopener">Verify enacted law at India Code ↗</a></div></section>
	{/if}
</section>

<style>
	.legal-page{width:min(100%,96rem);margin:auto;padding:clamp(2rem,5vw,5rem) clamp(1rem,3vw,2.5rem) 6rem;box-sizing:border-box}.hero{display:grid;grid-template-columns:1fr .8fr;gap:clamp(2rem,7vw,7rem);align-items:end;padding:3rem 0 5rem}.eyebrow{margin:0;color:var(--color-accent);font:600 var(--step--1)/1.2 var(--font-mono);letter-spacing:.08em;text-transform:uppercase}.hero h1{margin:.7rem 0 0;font:500 clamp(4.5rem,11vw,10rem)/.78 var(--font-serif);letter-spacing:-.06em}.lede{margin:0 0 1.5rem;font:500 clamp(1.5rem,2.8vw,2.6rem)/1.13 var(--font-serif)}.hero-copy>p:last-child{color:var(--color-text-muted);line-height:1.65}.loading,.notice{display:flex;gap:1rem;align-items:center;padding:2rem;border:1px solid var(--color-border);font-family:var(--font-mono)}.loading span{width:.8rem;height:.8rem;border-radius:50%;background:var(--color-accent)}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--color-border)}.stats div{padding:1.2rem;border-right:1px solid var(--color-border)}.stats div:last-child{border:0}.stats strong,.stats span{display:block}.stats strong{font:500 var(--step-1)/1.2 var(--font-serif)}.stats span{color:var(--color-text-muted);font:var(--step--2)/1.3 var(--font-mono);text-transform:uppercase}.filters{display:grid;grid-template-columns:2fr repeat(4,minmax(8rem,1fr));gap:.8rem;padding:1rem;margin-top:1rem;border:1px solid var(--color-border);background:var(--color-surface)}.filters label{min-width:0}.filters label>span{display:block;margin-bottom:.35rem;color:var(--color-text-muted);font:var(--step--2)/1.2 var(--font-mono);text-transform:uppercase}.filters input,.filters select{width:100%;min-width:0;height:2.7rem;padding:.55rem;box-sizing:border-box;border:1px solid var(--color-border);border-radius:var(--radius);background:var(--color-bg);color:var(--color-text)}.search,.wide{grid-column:span 2}.clear{align-self:end;height:2.7rem;border:1px solid var(--color-accent);background:transparent;color:var(--color-accent);cursor:pointer}.workspace{display:grid;gap:1rem;margin-top:1rem}.workspace.has-selection{grid-template-columns:1.15fr .85fr}.results,.detail{min-width:0;border:1px solid var(--color-border)}.result-head{display:flex;justify-content:space-between;padding:.8rem 1rem;border-bottom:1px solid var(--color-border);color:var(--color-text-muted);font:var(--step--2)/1.3 var(--font-mono);text-transform:uppercase}.result-head p{margin:0}.record{width:100%;display:grid;grid-template-columns:5rem minmax(0,1fr) 7rem;gap:1rem;padding:1rem;border:0;border-bottom:1px solid var(--color-border);background:transparent;color:var(--color-text);text-align:left;cursor:pointer}.record:hover,.record.selected{background:color-mix(in srgb,var(--color-accent) 7%,transparent)}.record-year,.record-status{color:var(--color-text-muted);font:var(--step--2)/1.35 var(--font-mono)}.record-main strong,.record-main small{display:block}.record-main strong{font:500 var(--step-0)/1.32 var(--font-serif)}.record-main small{margin-top:.3rem;color:var(--color-text-muted)}.record-status{text-align:right}.pagination{display:flex;align-items:center;justify-content:space-between;padding:1rem}.pagination button{padding:.55rem;border:1px solid var(--color-border);background:var(--color-bg);color:var(--color-text)}.pagination button:disabled{opacity:.35}.empty{padding:3rem 1rem;color:var(--color-text-muted)}.detail{position:sticky;top:5rem;align-self:start;max-height:calc(100vh - 6rem);overflow:auto;padding:clamp(1.2rem,3vw,2.2rem);background:var(--color-surface)}.close{float:right;border:0;background:none;color:var(--color-text);font-size:2rem}.detail-kicker{color:var(--color-accent);font:var(--step--2)/1.3 var(--font-mono);text-transform:uppercase}.detail h2{margin:.8rem 2rem 1.2rem 0;font:500 var(--step-3)/1.08 var(--font-serif)}.verification{padding:.7rem;border:1px solid var(--color-border);color:var(--color-text-muted);font:var(--step--2)/1.4 var(--font-mono)}.detail dl div{display:grid;grid-template-columns:8rem 1fr;gap:1rem;padding:.7rem 0;border-top:1px solid var(--color-border)}dt{color:var(--color-text-muted);font:var(--step--2)/1.35 var(--font-mono);text-transform:uppercase}dd{margin:0;font-size:var(--step--1)}.documents{padding-top:1rem;border-top:1px solid var(--color-border)}.documents h3{font:500 var(--step-1)/1.2 var(--font-serif)}.documents a{display:block;padding:.55rem 0;color:var(--color-accent);font:var(--step--1)/1.3 var(--font-mono);text-decoration:none}.method{display:grid;grid-template-columns:.8fr 1.2fr;gap:clamp(2rem,7vw,7rem);margin-top:5rem;padding-top:4rem;border-top:1px solid var(--color-border)}.method h2{font:500 var(--step-4)/1 var(--font-serif)}.method>div:last-child{color:var(--color-text-muted);line-height:1.65}.method a{color:var(--color-accent)}@media(max-width:1000px){.filters{grid-template-columns:repeat(3,1fr)}.workspace.has-selection{grid-template-columns:1fr}.detail{position:relative;top:auto;max-height:none;grid-row:1}}@media(max-width:700px){.hero,.method{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:1fr}.search,.wide{grid-column:auto}.record{grid-template-columns:3.5rem 1fr}.record-status{grid-column:2;text-align:left}.detail dl div{grid-template-columns:1fr;gap:.2rem}}
	.view-switch{display:flex;justify-content:flex-end;margin:1rem 0 .6rem}.view-switch button{padding:.55rem .9rem;border:1px solid var(--color-border);background:var(--color-bg);color:var(--color-text-muted);font:var(--step--2)/1.2 var(--font-mono);cursor:pointer}.view-switch button.active{border-color:var(--color-accent);background:var(--color-accent);color:white}.workspace.network-detail{display:block}.workspace.network-detail .results{display:none}.workspace.network-detail .detail{position:relative;top:auto;max-height:none;margin-top:1rem}
</style>
